import { useEffect } from 'react';
import styles from './SummaryCard.module.css';

const SummaryCard = ({ totalIncome, totalExpenses, balance, currentBalance }) => {
  // Guardar en localStorage cuando los props cambien
  useEffect(() => {
    localStorage.setItem('financialSummary', JSON.stringify({
      totalIncome,
      totalExpenses,
      balance,
      currentBalance,
    }));
  }, [totalIncome, totalExpenses, balance, currentBalance]);

  return (
    <div className={styles.card}>
      <h3>Resumen Financiero</h3>
      <div className={styles.summaryItem}>
        <p>Ingresos: ${totalIncome}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Gastos: ${totalExpenses}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Balance: ${balance}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Saldo Actual: ${currentBalance}</p>
      </div>
    </div>
  );
};

export default SummaryCard;
